func NewServer(ctx context.Context, profile *profile.Profile, store *store.Store) (*Server, error) {
	s := &Server{
		Store:   store,
		Profile: profile,
	}

	echoServer := echo.New()
	echoServer.Use(middleware.Recover())
	echoServer.Use(newCORSMiddleware(profile))
	s.echoServer = echoServer

	instanceBasicSetting, err := s.getOrUpsertInstanceBasicSetting(ctx)
	if err != nil {
		return nil, errors.Wrap(err, "failed to get instance basic setting")
	}

	secret := "usememos"
	if !profile.Demo {
		secret = instanceBasicSetting.SecretKey
	}
	s.Secret = secret

	// Register healthz endpoint.
	echoServer.GET("/healthz", func(c *echo.Context) error {
		return c.String(http.StatusOK, "Service ready.")
	})

	// Serve frontend static files.
	frontend.NewFrontendService(profile, store).Serve(ctx, echoServer)

	rootGroup := echoServer.Group("")

	apiV1Service := apiv1.NewAPIV1Service(s.Secret, profile, store)
	s.sseHub = apiV1Service.SSEHub

	// Register HTTP file server routes BEFORE gRPC-Gateway to ensure proper range request handling for Safari.
	// This uses native HTTP serving (http.ServeContent) instead of gRPC for video/audio files.
	fileServerService := fileserver.NewFileServerService(s.Profile, s.Store, s.Secret)
	fileServerService.RegisterRoutes(echoServer)

	// Create and register RSS routes (needs markdown service from apiV1Service).
	rss.NewRSSService(s.Profile, s.Store, apiV1Service.MarkdownService).RegisterRoutes(rootGroup)

	// Register gRPC gateway as api v1 (includes SSE endpoint on CORS-enabled group).
	if err := apiV1Service.RegisterGateway(ctx, echoServer); err != nil {
		return nil, errors.Wrap(err, "failed to register gRPC gateway")
	}

	mcpService, err := mcp.NewMCPService(profile, echoServer)
	if err != nil {
		return nil, errors.Wrap(err, "failed to create MCP service")
	}
	mcpService.RegisterRoutes(echoServer)

	return s, nil
}

func (s *FrontendService) Serve(_ context.Context, e *echo.Echo) {
	frontendFS := getFileSystem("dist")
	skipper := func(c *echo.Context) bool {
		requestPath := c.Request().URL.Path
		if shouldSkipFrontendStatic(requestPath) {
			return true
		}

		setFrontendCacheHeaders(c, requestPath)
		return false
	}

	// Route to serve the frontend static assets.
	e.Use(middleware.StaticWithConfig(middleware.StaticConfig{
		Filesystem: frontendFS,
		Skipper:    skipper,
	}))

	e.Use(spaFallbackMiddleware(frontendFS))
	s.registerRoutes(e)
}

func WithMiddleware(mw ...Middleware) Option {
	return func(s *Scheduler) {
		if len(mw) > 0 {
			s.middleware = Chain(mw...)
		}
	}
}

func Chain(middlewares ...Middleware) Middleware {
	return func(handler JobHandler) JobHandler {
		// Apply middleware in reverse order so first middleware wraps outermost
		for _, middleware := range slices.Backward(middlewares) {
			handler = middleware(handler)
		}
		return handler
	}
}

func newCORSMiddleware(profile *profile.Profile) echo.MiddlewareFunc {
	return middleware.CORSWithConfig(middleware.CORSConfig{
		// The API is open to any origin so that token-authenticated clients
		// (Access Token V2 / PAT in the Authorization header) can call it from
		// anywhere. Credentials ??? i.e. the SameSite=Lax refresh-token cookie ??? are
		// granted only to trusted origins (same host or the configured InstanceURL).
		//
		// AllowCredentials stays false here on purpose: the per-origin
		// Access-Control-Allow-Credentials header is set inside the func below.
		// Do NOT switch this to AllowCredentials:true ??? emitting that header for
		// every reflected origin would let a malicious same-site subdomain read the
		// cookie-authenticated /auth/refresh response and steal an access token.
		AllowCredentials: false,
		UnsafeAllowOriginFunc: func(c *echo.Context, origin string) (string, bool, error) {
			// Never reflect the opaque "null" origin (sandboxed iframes, file://).
			if origin == "null" {
				return "", false, nil
			}
			// Trusted origins additionally get credentialed (cookie) access.
			if isAllowedCORSOrigin(profile, c.Request().Host, origin) {
				c.Response().Header().Set(echo.HeaderAccessControlAllowCredentials, "true")
			}
			// Reflect every origin; only trusted ones carry the credentials header.
			return origin, true, nil
		},
	})
}

func (s *Scheduler) runJobWithSchedule(ctx context.Context, rj *registeredJob, schedule *Schedule) {
	defer s.wg.Done()

	// Apply middleware to handler
	handler := rj.job.Handler
	if s.middleware != nil {
		handler = s.middleware(handler)
	}

	for {
		// Calculate next run time
		now := time.Now()
		if rj.job.Timezone != "" {
			loc, err := time.LoadLocation(rj.job.Timezone)
			if err == nil {
				now = now.In(loc)
			}
		} else if s.timezone != nil {
			now = now.In(s.timezone)
		}

		next := schedule.Next(now)
		duration := time.Until(next)

		timer := time.NewTimer(duration)

		select {
		case <-timer.C:
			// Add job name to context and execute
			jobCtx := withJobName(ctx, rj.job.Name)
			if err := handler(jobCtx); err != nil {
				// Error already handled by middleware (if any)
				_ = err
			}
		case <-ctx.Done():
			// Stop the timer to prevent it from firing. The timer will be garbage collected.
			timer.Stop()
			return
		case <-s.stopCh:
			// Stop the timer to prevent it from firing. The timer will be garbage collected.
			timer.Stop()
			return
		}
	}
}

func (s *APIV1Service) RegisterGateway(ctx context.Context, echoServer *echo.Echo) error {
	// Shared authorizer: one source of truth for authentication and anonymous-access
	// policy, used by both the gRPC-Gateway middleware and the Connect interceptor.
	authorizer := NewAuthorizer(s.Store, s.Secret, s.Profile)
	gatewayAuthMiddleware := func(next runtime.HandlerFunc) runtime.HandlerFunc {
		return func(w http.ResponseWriter, r *http.Request, pathParams map[string]string) {
			ctx := r.Context()

			// The RPC method name is set by grpc-gateway after routing. When it can't be
			// determined, skip the policy check and let the service layer handle visibility.
			rpcMethod, ok := runtime.RPCMethod(ctx)
			authHeader := r.Header.Get("Authorization")

			result := authorizer.Authenticate(ctx, authHeader)
			if ok {
				if err := authorizer.CheckAccess(ctx, rpcMethod, result); err != nil {
					http.Error(w, `{"code": 16, "message": "authentication required"}`, http.StatusUnauthorized)
					return
				}
			}

			// Apply the identity to the context (no-op for permitted anonymous requests).
			if result != nil {
				r = r.WithContext(auth.ApplyToContext(ctx, result))
			}

			next(w, r, pathParams)
		}
	}

	// Create gRPC-Gateway mux with auth middleware.
	gwMux := runtime.NewServeMux(
		runtime.WithMiddlewares(gatewayAuthMiddleware),
	)
	if err := v1pb.RegisterInstanceServiceHandlerServer(ctx, gwMux, s); err != nil {
		return err
	}
	if err := v1pb.RegisterAuthServiceHandlerServer(ctx, gwMux, s); err != nil {
		return err
	}
	if err := v1pb.RegisterUserServiceHandlerServer(ctx, gwMux, s); err != nil {
		return err
	}
	if err := v1pb.RegisterMemoServiceHandlerServer(ctx, gwMux, s); err != nil {
		return err
	}
	if err := v1pb.RegisterAttachmentServiceHandlerServer(ctx, gwMux, s); err != nil {
		return err
	}
	if err := v1pb.RegisterAIServiceHandlerServer(ctx, gwMux, s); err != nil {
		return err
	}
	if err := v1pb.RegisterShortcutServiceHandlerServer(ctx, gwMux, s); err != nil {
		return err
	}
	if err := v1pb.RegisterIdentityProviderServiceHandlerServer(ctx, gwMux, s); err != nil {
		return err
	}
	gwGroup := echoServer.Group("")
	// Register SSE endpoint with same CORS as rest of /api/v1.
	RegisterSSERoutes(gwGroup, s.SSEHub, s.Store, s.Secret)
	handler := echo.WrapHandler(http.MaxBytesHandler(gwMux, maxAPIRequestBytes))

	gwGroup.Any("/api/v1/*", handler)
	gwGroup.Any("/file/*", handler)

	// Connect handlers for browser clients (replaces grpc-web).
	logStacktraces := s.Profile.Demo
	connectInterceptors := connect.WithInterceptors(
		NewMetadataInterceptor(), // Convert HTTP headers to gRPC metadata first
		NewLoggingInterceptor(logStacktraces),
		NewRecoveryInterceptor(logStacktraces),
		NewAuthInterceptor(authorizer),
	)
	connectMux := http.NewServeMux()
	connectHandler := NewConnectServiceHandler(s)
	connectHandler.RegisterConnectHandlers(connectMux, connectInterceptors, connect.WithReadMaxBytes(maxAPIRequestBytes))

	connectGroup := echoServer.Group("")
	connectGroup.Any("/memos.api.v1.*", echo.WrapHandler(http.MaxBytesHandler(connectMux, maxAPIRequestBytes)))

	return nil
}

func listDeleteUserMemoTreeIterative(ctx context.Context, tx *sql.Tx, userID int32) ([]deleteUserMemoRef, error) {
	roots, err := queryDeleteUserMemoRefs(ctx, tx, `
		SELECT id, uid
		FROM memo
		WHERE creator_id = `+deleteUserPlaceholder(1), userID)
	if err != nil {
		return nil, err
	}

	memos := make([]deleteUserMemoRef, 0, len(roots))
	seen := make(map[int32]struct{})
	frontier := make([]int32, 0, len(roots))
	for _, memo := range roots {
		if _, exists := seen[memo.ID]; exists {
			continue
		}
		seen[memo.ID] = struct{}{}
		memos = append(memos, memo)
		frontier = append(frontier, memo.ID)
	}

	for len(frontier) > 0 {
		currentFrontier := frontier
		nextFrontier := make([]int32, 0)
		for _, batch := range deleteUserBatches(currentFrontier, deleteUserBatchSize) {
			clause, args := deleteUserInClause(1, batch)
			children, err := queryDeleteUserMemoRefs(ctx, tx, `
				SELECT child.id, child.uid
				FROM memo child
				JOIN memo_relation rel ON rel.memo_id = child.id AND rel.type = 'COMMENT'
				WHERE rel.related_memo_id IN `+clause, args...)
			if err != nil {
				return nil, err
			}

			for _, child := range children {
				if _, exists := seen[child.ID]; exists {
					continue
				}
				seen[child.ID] = struct{}{}
				memos = append(memos, child)
				nextFrontier = append(nextFrontier, child.ID)
			}
		}
		frontier = nextFrontier
	}

	return memos, nil
}

