  const ordered = ORDERED_ITEM.exec(text);
  if (ordered) {
    const [, , , delimiter, spaces, content] = ordered;
    return `${" ".repeat(indent)}${nextOrderedNumber(doc, lineNumber, indent)}${delimiter}${spaces}${content}`;
